# Reviewed under AGENTS.md
import csv

rows = []
with open("contacts.csv", newline="") as f:
    reader = csv.DictReader(f)
    for idx, r in enumerate(reader):
        rows.append((idx, r["name"], r["email"].strip().lower(), r["created"].strip()))

best = {}
for idx, name, email, created in rows:
    if email not in best:
        best[email] = (idx, name, email, created)
    else:
        cur = best[email]
        if created < cur[3]:
            best[email] = (idx, name, email, created)

out = sorted(best.values(), key=lambda t: (t[3], t[2]))

with open("clean.csv", "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["name", "email", "created"])
    for idx, name, email, created in out:
        w.writerow([name, email, created])
